40|  canSkip: boolean;
41|  onSkip: () => void;
42|  volume: number;
43|  muted: boolean;
44|  onVolumeChange: (volume: number) => void;
45|  onMutedChange: (muted: boolean) => void;
46|  styles: StyleInfo[];
47|  styleId: string | null;
48|  onStyleChange: (style: string) => void;
49|  onEnded: (trackId: string) => void;
50|  playlistOn: boolean;
51|  playlistLabel: string | null;
52|  onTogglePlaylist: () => void;
