61|  // Slider value and mute live in the reader (persisted prefs); refs
62|  // mirror the props so the engine never re-runs on volume moves.
63|  const volumeRef = useRef(volume);
64|  volumeRef.current = volume;
65|  const mutedRef = useRef(muted);
66|  mutedRef.current = muted;
67|  const fadeRef = useRef<number | null>(null);
68|  const loopArmedRef = useRef<string | null>(null);
69|  const trackRef = useRef<Track | null>(track);
70|  trackRef.current = track;
71|  const fadeSecRef = useRef(fadeSec);
72|  fadeSecRef.current = fadeSec;
73|  const onEndedRef = useRef(onEnded);
74|  onEndedRef.current = onEnded;
75|  const playingRef = useRef(false);
76|  const startedRef = useRef(false);
77|  const firstPlayRef = useRef(true);
78|
79|  // Scheduler fade when set, else the config default; never 0 mid session.
80|  function loopFadeSec() {
81|    return fadeSecRef.current > 0 ? fadeSecRef.current : MUSIC_CONFIG.crossfadeSec;
82|  }
83|  const [started, setStarted] = useState(false);
84|  const [playing, setPlaying] = useState(false);
85|  const requestPlayRef = useRef((_: Track, __: number) => {});
