87|  const [reducedMotion, setReducedMotion] = useState(
88|    () =>
89|      typeof window !== "undefined" &&
90|      !!window.matchMedia?.("(prefers-reduced-motion: reduce)").matches,
91|  );
92|
93|  useEffect(() => {
94|    const query = window.matchMedia?.("(prefers-reduced-motion: reduce)");
95|    if (!query) return;
96|    const onChange = (event: MediaQueryListEvent) => setReducedMotion(event.matches);
97|    query.addEventListener("change", onChange);
98|    return () => query.removeEventListener("change", onChange);
99|  }, []);
